-- Refreshes product names, brands, prices, descriptions and catalog photos from catalog.json, matched by SKU.
-- Stock, availability and ids are NOT touched, so carts and orders stay valid (order_items keep their own
-- product_name snapshot). A photo uploaded by an admin (/api/products/images/...) is never replaced.
-- Safe to run more than once.
-- Usage: docker exec -i quickkart-postgres psql -U postgres -d quickkart -v ON_ERROR_STOP=1 < scripts/database/refresh-catalog-details.sql
BEGIN;
UPDATE products p SET name = v.name, brand = v.brand, price = v.price, discount_percentage = v.discount,
       rating = v.rating, review_count = v.reviews, description = v.description,
       image_url = CASE WHEN p.image_url LIKE '/api/products/images/%' THEN p.image_url ELSE v.image END,
       thumbnail_url = CASE WHEN p.thumbnail_url LIKE '/api/products/images/%' THEN p.thumbnail_url ELSE v.image END
